/* Navigation-only enhancements. No credentials, persistence or API requests. */
(() => {
 const $=s=>document.querySelector(s), make=(tag,cls,text)=>{const el=document.createElement(tag);if(cls)el.className=cls;if(text)el.textContent=text;return el;};
 const header=$('.site-header');
 const source=document.body.dataset.view==='panel'?$('#adminNavigation'):$('#portal-main-nav');
 if(source&&document.body.dataset.view==='panel'){
  const toggle=make('button','panel-section-toggle');toggle.type='button';toggle.setAttribute('aria-controls','adminNavigation');toggle.setAttribute('aria-expanded','false');source.before(toggle);const compact=window.matchMedia('(max-width:700px)');
  const current=()=>{toggle.textContent=(source.querySelector('a[aria-current="page"]')?.textContent.trim()||'Seções do painel')+' ▾';};
  const sync=()=>{toggle.hidden=!compact.matches;source.hidden=compact.matches;toggle.setAttribute('aria-expanded','false');current();};
  toggle.addEventListener('click',()=>{source.hidden=!source.hidden;toggle.setAttribute('aria-expanded',String(!source.hidden));});source.addEventListener('click',e=>{if(e.target.closest('a')&&compact.matches){source.hidden=true;toggle.setAttribute('aria-expanded','false');}});source.addEventListener('keydown',e=>{if(e.key==='Escape'&&compact.matches){source.hidden=true;toggle.setAttribute('aria-expanded','false');toggle.focus();}});window.addEventListener('hashchange',current);compact.addEventListener('change',sync);sync();
 }
 if(header&&source&&typeof HTMLDialogElement!=='undefined'){
  const launch=make('button','site-search');launch.type='button';launch.setAttribute('aria-label','Buscar página ou função');launch.title='Buscar página ou função (Ctrl + K)';launch.innerHTML='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/></svg>';header.append(launch);
  const dialog=make('dialog','quick-dialog');dialog.setAttribute('aria-label','Navegação rápida');const top=make('div','quick-dialog-head');top.append(make('label','','Aonde você quer ir?'));const close=make('button','','Fechar');close.type='button';top.append(close);dialog.append(top);const input=make('input');input.type='search';input.placeholder='Buscar página ou função…';input.setAttribute('aria-label','Buscar página ou função');dialog.append(input);const links=make('div','quick-links');dialog.append(links);const empty=make('p','quick-empty','Nenhuma página encontrada. Tente outro termo.');empty.hidden=true;dialog.append(empty);dialog.append(make('p','quick-hint','Use Tab para navegar • Esc para fechar'));document.body.append(dialog);
  const normalize=v=>v.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
  const refresh=()=>{links.replaceChildren();const entries=[...source.querySelectorAll('a')].filter(a=>!a.hidden&&getComputedStyle(a).display!=='none');if(document.body.dataset.view!=='panel')entries.push(...['/seguranca/','/privacidade'].map((href,i)=>{const a=document.createElement('a');a.href=href;a.textContent=i?'Privacidade':'Segurança';return a;}));let count=0;for(const a of entries){if(!normalize(a.textContent).includes(normalize(input.value)))continue;const link=make('a','',a.textContent.trim());link.href=a.getAttribute('href');link.append(make('span','','↗'));link.onclick=()=>dialog.close();links.append(link);count++;}empty.hidden=count>0;};
  const open=()=>{input.value='';dialog.showModal();refresh();input.focus();};launch.onclick=open;close.onclick=()=>dialog.close();input.addEventListener('input',refresh);document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'&&!e.repeat){e.preventDefault();if(dialog.open)dialog.close();else open();}});
 }
 const grid=$('.platform-grid');if(grid){const bar=make('div','platform-finder'),label=make('label','','Encontre seu aparelho');label.htmlFor='platformSearch';const input=make('input');input.id='platformSearch';input.type='search';input.placeholder='Ex.: Roku, Samsung, Fire TV…';const output=make('output');output.setAttribute('aria-live','polite');bar.append(label,input,output);grid.before(bar);const cards=[...grid.querySelectorAll('.platform-card')];const empty=make('p','platform-no-results','Não encontramos essa plataforma. Confira o modelo do aparelho ou fale com o suporte.');empty.hidden=true;grid.append(empty);const filter=()=>{let n=0;const term=input.value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();for(const card of cards){const text=card.textContent.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();card.hidden=!text.includes(term);if(!card.hidden)n++;}output.textContent=`${n} de ${cards.length} plataformas`;empty.hidden=n>0;};input.addEventListener('input',filter);document.querySelectorAll('.portal-platform-jump a').forEach(a=>a.addEventListener('click',()=>{input.value='';filter();}));filter();}
 const back=make('button','back-top','↑');back.type='button';back.hidden=true;back.setAttribute('aria-label','Voltar ao início da página');document.body.append(back);back.onclick=()=>window.scrollTo({top:0,behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});let queued=false;const sync=()=>{back.hidden=window.scrollY<650;queued=false;};window.addEventListener('scroll',()=>{if(!queued){queued=true;requestAnimationFrame(sync);}},{passive:true});sync();
})();